'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isComplexLike = require( '@stdlib/assert/is-complex-like' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var factory = require( './../lib' );


// MAIN //

bench( format( '%s::complex128:every', pkg ), function benchmark( b ) {
	var Complex128Array;
	var bool;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( [ 1, 2, 3, 4 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		bool = arr.every( predicate );
		if ( typeof bool !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( bool ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();

	function predicate( v ) {
		return isComplexLike( v );
	}
});

bench( format( '%s::complex64:every', pkg ), function benchmark( b ) {
	var Complex64Array;
	var bool;
	var arr;
	var i;

	Complex64Array = factory( 'complex64' );
	arr = new Complex64Array( [ 1, 2, 3, 4 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		bool = arr.every( predicate );
		if ( typeof bool !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( bool ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();

	function predicate( v ) {
		return isComplexLike( v );
	}
});
